"after 28 days": "a los 28 días",
"Select all shown": "Seleccionar todo lo visible",
"Like the checked": "Me gusta a las marcadas",
"Like every checked take (all liked already: taken back)": "Me gusta a cada toma marcada (si ya lo tenían todas: se retira)",
"Dislike the checked": "No me gusta a las marcadas",
