"Search runs · set · kind": "Buscar ejecuciones · conjunto · tipo",
"The server log, in every room: click to unfold or fold": "El registro del servidor, en cada sala: clic para desplegar o plegar",
"The line to the studio: the round trip, the middle of the last five (every 20 s). Near: the studio answers at once.": "La línea hasta el estudio: ida y vuelta, la mediana de las últimas cinco (cada 20 s). Cerca: el estudio responde al instante.",
"Follow: the log keeps to its newest line as the engine writes. Off: it stays where you scrolled to read.": "Seguir: el registro se queda en su línea más reciente mientras el motor escribe. Apagado: se queda donde lo desplazaste para leer.",
"The whole log, in Engine": "El registro completo, en Motor",
"Unfold the takes list": "Desplegar la lista de tomas",
