"Fold the takes list to the right": "Plegar la lista de tomas a la derecha",
"Library actions": "Acciones de la biblioteca",
"Show": "Mostrar",
"Liked only": "Solo las que me gustan",
"From all Workspaces": "De todos los espacios",
"Every workspace's takes in this column, whatever workspace is in hand (new takes still land in that one); the column's other filters still apply": "Las tomas de todos los espacios en esta columna, sea cual sea el espacio en uso (las tomas nuevas siguen yendo a ese); los demás filtros de la columna siguen valiendo",
"Without the disliked": "Sin las que no me gustan",
