"Search · * and ? work": "Buscar · * y ? funcionan",
"Finds takes here by title or library name: * stands for any letters, ? for one. The column's filters still apply.": "Encuentra tomas aquí por título o nombre en la biblioteca: * vale por cualquier letra, ? por una. Los filtros de la columna siguen aplicándose.",
