"Each song renders {#0} times with sound seeds seed, seed + 1…; the music is written once.": {"one": "Cada canción se renderiza {0} vez con las semillas sonoras seed, seed + 1…; la música se escribe una vez.", "many": "Cada canción se renderiza {0} veces con las semillas sonoras seed, seed + 1…; la música se escribe una vez.", "other": "Cada canción se renderiza {0} veces con las semillas sonoras seed, seed + 1…; la música se escribe una vez."},
