"experimental": "experimental",
"It works and was checked, but it still needs crash tests on other machines and projects, and more work": "Funciona y se ha comprobado, pero aún necesita pruebas de fallos en otras máquinas y proyectos, y más trabajo",
"The whole take as a project of your DAW: the stems on their tracks, the score as MIDI, the tempo, the sections as regions, the lyrics on the timeline. Which DAW do you use?": "La toma entera como proyecto de tu DAW: los stems en sus pistas, la partitura como MIDI, el tempo, las secciones como regiones, la letra en la línea de tiempo. ¿Qué DAW usas?",
