"All the music strengths together. Measured on this studio's takes: the score came out whole up to {0} in every run, broken from 2.5 in every run. Green to {1}, amber to {2}, red past it.": "Todas las intensidades musicales juntas. Medido en las tomas de este estudio: la partitura salió entera hasta {0} en cada ejecución, y rota desde 2.5 en cada ejecución. Verde hasta {1}, ámbar hasta {2}, rojo más allá.",
