"⚠ {0}: {1} on the music half is past its limit {2}: the score tends to fail after 70-200 tokens.": "⚠ {0}: {1} en la mitad musical supera su límite {2}: la partitura suele fallar tras 70-200 tokens.",
"⚠ {0}: {1} on the sound half is past its limit {2}.": "⚠ {0}: {1} en la mitad sonora supera su límite {2}.",
"⚠ {0} plans instrumental scores: at {1} with words to sing, the score loses its vocal line (measured at 1.00: 1 note in 127 vocal bars, the music looping). Keep it low, 0.3–0.5, for a sung song.": "⚠ {0} planifica partituras instrumentales: a {1} con palabras para cantar, la partitura pierde su línea vocal (medido a 1.00: 1 nota en 127 compases vocales, con la música en bucle). Mantenla baja, 0.3–0.5, para una canción cantada.",
"{#0} stacked: their changes add up.": "{0} apiladas: sus cambios se suman.",
"⚠ The music half carries {0} together, past the shared ceiling {1}: runs this heavy wrote broken scores every time (measured). Lower some, or take one off the music half.": "⚠ La mitad musical lleva {0} en conjunto, por encima del techo común {1}: las ejecuciones así de pesadas escribieron partituras rotas cada vez (medido). Baja alguna, o quita una de la mitad musical.",
