"Four adapters at most: take one off first": "Cuatro adaptadores como mucho: quita uno antes",
"Already in the prompt: {0}": "Ya está en el prompt: {0}",
"Take it off": "Quitar",
"Its strength": "Su fuerza",
"The adapters for {0}": "Los adaptadores para {0}",
"LoRA for {0}": "LoRA para {0}",
