"How often the studio asks GitHub for the list of its releases, nothing more. Never: only when you press Check now": "Cada cuánto pide el estudio a GitHub la lista de sus versiones, nada más. Nunca: solo cuando pulses «Comprobar ahora»",
"Ask: a window says what is new, and you choose. Update by itself: when nothing runs, the studio fetches it, builds it and restarts (only where it is a clone of its repository)": "Preguntar: una ventana dice qué hay de nuevo, y tú eliges. Actualizar solo: cuando nada corre, el estudio la descarga, la compila y se reinicia (solo donde es un clon de su repositorio)",
