"Ruach Studio {0} · not looked yet": "Ruaj Estudio {0} · aún sin comprobar",
"Ruach Studio {0} · could not ask GitHub: {1}": "Ruaj Estudio {0} · no se pudo preguntar a GitHub: {1}",
"{#0} days ago": { "one": "hace {#0} día", "other": "hace {#0} días" },
"Could not ask GitHub: {0}": "No se pudo preguntar a GitHub: {0}",
"Up to date: {0}": "Al día: {0}",
"No answer: {0}": "Sin respuesta: {0}",
"A run is going: the update waits until nothing runs": "Hay una ejecución en marcha: la actualización espera a que nada corra",
"Updating to {0}: the studio builds it, then restarts": "Actualizando a {0}: el estudio la compila y luego se reinicia",
