"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "La toma en mano fuera del estudio: la pista mezclada tal cual, o la toma entera a tu DAW (con sus stems, una vez separados aquí)",
