"Coiled horn: noble, warm, heroic and distant.": "Trompa enroscada: noble, cálida, heroica y lejana.",
"Bright brass: fanfare, brilliance, a clear call.": "Metal brillante: fanfarria, brillo, una llamada clara.",
"Slide brass: broad, warm, can glide between notes.": "Metal de vara: amplio, cálido, puede deslizarse entre notas.",
