"Church organ: sustained chords, huge and sacred, notes without decay.": "Órgano de iglesia: acordes sostenidos, enormes y sagrados, notas sin decaimiento.",
"Pumped reed organ: wheezing, warm, devotional.": "Órgano de lengüetas de fuelle: resollante, cálido, devocional.",
