"Struck bronze disc: a swelling, roaring wash.": "Disco de bronce golpeado: una oleada que crece y ruge.",
"Tuned kettledrums: thunder rolls and pitched booms.": "Timbales afinados: redobles de trueno y retumbos con altura.",
"Big Japanese drums: massive, ceremonial, physical hits.": "Grandes tambores japoneses: golpes masivos, ceremoniales, físicos.",
