"Nylon-string guitar: soft, round, intimate.": "Guitarra de cuerdas de nailon: suave, redonda, íntima.",
"Amplified guitar: clean to distorted, sustain and bite.": "Guitarra amplificada: de limpia a distorsionada, sustain y mordida.",
"Electric bass: the low line under a band.": "Bajo eléctrico: la línea grave bajo una banda.",
"Bellows and reeds: breathing chords, folk, café, tango.": "Fuelle y lengüetas: acordes que respiran, folk, café, tango.",
"Bag-fed chanter over drones: loud, martial, continuous.": "Puntero alimentado por un fuelle sobre bordones: fuerte, marcial, continuo.",
"A sustained synthetic wash: soft chords, no attack.": "Un manto sintético sostenido: acordes suaves, sin ataque.",
