"master": "máster",
"a file": "un archivo",
"a set of stems": "un conjunto de stems",
"one stem": "un stem",
"{0} takes no {1}": "{0} no toma {1}",
"The take in hand: what every step starts from. A click opens the Takes, to pick another": "La toma en uso: de ella parte cada paso. Un clic abre las Tomas, para elegir otra",
"The chain: its profile, Run the chain and On the workspace…; it runs the way drawn thick": "La cadena: su perfil, Ejecutar la cadena y En el espacio…; ejecuta el camino dibujado en grueso",
"A track from anywhere (WAV, FLAC, MP3…) into the library as a take, marked imported; a way wired from here runs on each one imported next": "Una pista de cualquier lugar (WAV, FLAC, MP3…) a la biblioteca como toma, marcada como importada; un camino trazado desde aquí se ejecuta solo en cada importación siguiente",
"Every file made from this take, each under the one it came from: play, compare, rate, delete": "Cada archivo creado a partir de esta toma, bajo aquel del que salió: escuchar, comparar, valorar, borrar",
"The spectrum of the take or of a file made from it: how loud each band is, over time": "El espectro de la toma o de un archivo creado de ella: qué tan fuerte suena cada banda en el tiempo",
"Faults measured in a file: clicks, clipping, the frame buzz, a hum": "Fallos medidos en un archivo: clics, saturación, el zumbido de los cuadros, un hum",
"The lyrics held against what is sung (Whisper): which lines came and which did not": "La letra frente a lo cantado (Whisper): qué líneas llegaron y cuáles no",
"The frame buzz of YuE2's sound out of the take: needed for every YuE2 take, off for a track from elsewhere": "El zumbido de cuadro del sonido de YuE2 fuera de la toma: necesario en cada toma de YuE2, apagado para una pista ajena",
"UniverSR redraws the top of the spectrum above a cutoff, the original kept below it": "UniverSR vuelve a dibujar la parte alta del espectro por encima de un corte, debajo queda el original",
"The file split into stems: four, six, eight, or the voice and the rest": "El archivo separado en stems: cuatro, seis, ocho, o la voz y el resto",
"The stems on lanes: levels, versions, buses and automation, then a mix": "Los stems en pistas: niveles, versiones, buses y automatización, luego una mezcla",
"The Digital Gateway: tape, console and tube in numbers, on a file or a mix": "La pasarela digital: cinta, consola y válvula en números, sobre un archivo o una mezcla",
"The Debunker: a file or a set of stems balanced, compressed, toned and brought to a loudness": "El Debunker: un archivo o un conjunto de stems equilibrado, comprimido, ecualizado y llevado a una sonoridad",
"This machine's interfaces: the gateway's out and in, the monitor": "Las interfaces de esta máquina: la salida y la entrada de la pasarela, el monitor",
"The way: what the chain runs, step to step": "El camino: lo que ejecuta la cadena, paso a paso",
"Made: which file came from which": "Hecho: qué archivo salió de cuál",
"A step's own source, for a run from its window": "El origen propio de un paso, para ejecutarlo desde su ventana",
"Drag from a node's dot onto another: it joins the way after it; the nodes that can take it light up": "Arrastra desde el punto de un nodo hasta otro: entra en el camino después de él; se iluminan los nodos que pueden tomarlo",
"Fold the legend": "Plegar la leyenda",
"Unfold the legend": "Desplegar la leyenda",
"{0} was not on your way: it stands where its kind goes": "{0} no estaba en tu camino: se coloca donde va su tipo",
"The DAW's lanes take {0}'s newest: {1} of them": "Las pistas del DAW toman lo más nuevo de {0}: {1}",
"Nothing of {0} for the DAW's lanes yet: run it, or put it on the way": "Aún nada de {0} para las pistas del DAW: ejecútalo o ponlo en el camino",
