"Playlist · {#0} / {#1}": "Playlist · {0} / {1}",
"Without a note": "Sin nota",
// HERESY 1734: why the wave's section edits are greyed
"Sections and lyrics on the wave are off (the player's switch)": "Las secciones y la letra en la onda están apagadas (el interruptor del reproductor)",
"These are the score's marks: Find the sections by ear first (in this menu)": "Son marcas de la partitura: primero «Encontrar las secciones de oído» (en este menú)",
"No sections on the wave yet: Find the sections by ear (in this menu)": "Aún no hay secciones en la onda: «Encontrar las secciones de oído» (en este menú)",
"No section under the pointer": "No hay ninguna sección bajo el puntero",
"The rest of a part sung anew: the pointer over the part itself": "El resto de una parte cantada de nuevo: el puntero sobre la parte misma",
